
(()=>{'use strict';
const nav=document.querySelector('header.top nav')||document.querySelector('header nav');if(!nav)return;
const launch=document.createElement('button');launch.id='hiw-launch';launch.type='button';launch.textContent='HOW I WORK';launch.setAttribute('aria-haspopup','dialog');nav.insertBefore(launch,document.getElementById('tech-matrix-launch')||nav.lastElementChild);
const cases=[
{title:'Wachstum messbar machen',short:'Ziele, Kanäle und Wirkung verbinden',headline:'Vom digitalen Kanal zum Umsatzbeitrag',challenge:'Digitaler Vertrieb muss wirtschaftliche Wirkung zeigen – nicht nur Reichweite oder Klickzahlen.',approach:'Mein Arbeitsansatz: Geschäftsziele und Customer Journey zusammen betrachten, Maßnahmen priorisieren und Ergebnisse anhand relevanter Kennzahlen bewerten.',fact:'Unter 5 Mio. € → über 10 Mio. €',proof:'Entwicklung des Online-Umsatzes innerhalb von drei Jahren; Unternehmensleistung mit wesentlichem persönlichem Beitrag.',open:'Welche drei Maßnahmen hast du selbst initiiert oder verantwortet? Welche KPIs hast du regelmäßig gesteuert?',world:0},
{title:'Technologie nutzbar machen',short:'Komplexität in Kundennutzen übersetzen',headline:'Digitale Produkte müssen echte Probleme lösen',challenge:'Komplexe Produkte und gewachsene Systemlandschaften erschweren einen einfachen digitalen Kauf- und Anfrageprozess.',approach:'Mein Arbeitsansatz: Anforderungen aus Vertrieb, Produkt und Technik zusammenführen, eine nutzbare Lösung gestalten und die Integration in bestehende Prozesse mitdenken.',fact:'250+ Leads pro Monat',proof:'B2B2C-3D-Produktkonfigurator mit ERP- und Fertigungsanbindung.',open:'Was war deine genaue Projektrolle? Welche Entscheidungen lagen bei dir? Wie werden die Leads qualifiziert?',world:1},
{title:'Teams und Märkte verbinden',short:'Orientierung schaffen, Verantwortung klären',headline:'Internationale Umsetzung braucht klare Prioritäten',challenge:'Unterschiedliche Märkte, Teams und Partner müssen auf gemeinsame Ziele ausgerichtet werden, ohne lokale Anforderungen zu ignorieren.',approach:'Mein Arbeitsansatz: Ziele transparent machen, Verantwortlichkeiten definieren und einen verlässlichen Austausch zwischen zentralen und lokalen Beteiligten fördern.',fact:'Bis zu 9 Mitarbeiter · 13 Tochtergesellschaften',proof:'Führungserfahrung und internationale Steuerung digitaler Aktivitäten; zusätzlich drei exklusive Vertriebspartner.',open:'Wie war dein Team aufgebaut? Welche Entscheidungen hast du selbst getroffen? Ein konkretes Führungsbeispiel ergänzen.',world:2}
];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='beyondcv_how_i_work_v85';let notes={};try{const raw=JSON.parse(localStorage.getItem(KEY)||'{}');if(raw&&typeof raw==='object'&&!Array.isArray(raw))notes=raw;}catch{}
const panel=document.createElement('section');panel.id='hiw-panel';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-labelledby','hiw-title');panel.innerHTML=`<div class="hiw-wrap"><div class="hiw-top"><span class="hiw-kicker">BEYOND THE CV / WORKING PRINCIPLES</span><button type="button" class="hiw-close" id="hiw-close" aria-label="Ansicht schließen">✕ SCHLIESSEN</button></div><h2 id="hiw-title">How I <span style="color:#83dfff">Work.</span></h2><p class="hiw-lead">Drei Perspektiven darauf, wie ich digitale Herausforderungen angehe. Die Beispiele zeigen belegte Projektergebnisse; die beschriebenen Arbeitsprinzipien sind eine redaktionelle Einordnung und können von mir konkretisiert werden.</p><div class="hiw-grid" id="hiw-choices" role="tablist" aria-label="Arbeitsprinzip auswählen"></div><div id="hiw-detail" class="hiw-detail" role="tabpanel" aria-live="polite"></div><div class="hiw-edit"><div class="hiw-label">Mein konkretes Beispiel – zur Ergänzung</div><label for="hiw-notes">Hier kann ich eine eigene Entscheidung, Situation oder Vorgehensweise dokumentieren. Diese Notiz ist zunächst nur lokal sichtbar.</label><textarea id="hiw-notes" maxlength="1600" placeholder="Beispiel: Ausgangslage, meine Entscheidung, Zusammenarbeit und Ergebnis …"></textarea><div class="hiw-footer"><button type="button" id="hiw-save" class="hiw-action primary">Notiz lokal speichern</button><button type="button" id="hiw-export" class="hiw-action">Alle Notizen als JSON sichern</button><button type="button" id="hiw-import" class="hiw-action">JSON importieren</button><input id="hiw-file" type="file" accept="application/json,.json" hidden></div><p id="hiw-status" class="hiw-status" role="status"></p></div><p class="hiw-disclaimer">Wichtig: Diese Ansicht speichert persönliche Ergänzungen ausschließlich im aktuellen Browser. Der HTML-Veröffentlichungsexport und das serverseitige Content Studio übernehmen diese Notizen noch nicht automatisch. Sichere sie vor einem Browserwechsel über JSON.</p></div>`;document.body.append(panel);
let active=0,previous=null;
function render(){document.getElementById('hiw-choices').innerHTML=cases.map((x,i)=>`<button type="button" role="tab" class="hiw-choice" data-index="${i}" id="hiw-tab-${i}" aria-controls="hiw-detail" aria-selected="${i===active}" tabindex="${i===active?0:-1}"><span class="hiw-num">0${i+1} / PRINCIPLE</span><strong>${esc(x.title)}</strong><small>${esc(x.short)}</small></button>`).join('');const c=cases[active];document.getElementById('hiw-detail').innerHTML=`<div><div class="hiw-label">Herausforderung</div><h3>${esc(c.headline)}</h3><p>${esc(c.challenge)}</p><div class="hiw-label">Mein Arbeitsansatz</div><p>${esc(c.approach)}</p></div><div><div class="hiw-label">Beleg aus meiner Erfahrung</div><div class="hiw-fact"><strong>${esc(c.fact)}</strong><p>${esc(c.proof)}</p></div><div class="hiw-label">Für ein noch stärkeres Beispiel</div><p>${esc(c.open)}</p><button type="button" class="hiw-action" id="hiw-world">Kompetenzwelt ${active+1} öffnen →</button></div>`;document.getElementById('hiw-notes').value=notes[active]||'';document.getElementById('hiw-status').textContent='';document.getElementById('hiw-world').addEventListener('click',()=>{close();const nodes=[...document.querySelectorAll('[data-world]')];const target=nodes.find(n=>Number(n.dataset.world)===active)||nodes[active];if(target)target.click();else{document.getElementById('homeBtn')?.click();document.getElementById('hiw-status').textContent='Kompetenzwelt bitte über den Hub auswählen.';}});}
function open(){previous=document.activeElement;panel.hidden=false;document.body.style.overflow='hidden';render();document.getElementById('hiw-close').focus()}
function close(){panel.hidden=true;document.body.style.overflow='';if(previous?.isConnected)previous.focus()}
launch.addEventListener('click',open);document.getElementById('hiw-close').addEventListener('click',close);
document.getElementById('hiw-choices').addEventListener('click',e=>{const tab=e.target.closest('[data-index]');if(!tab)return;active=Number(tab.dataset.index);render();document.getElementById('hiw-tab-'+active).focus()});
document.getElementById('hiw-choices').addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();active=e.key==='Home'?0:e.key==='End'?cases.length-1:(active+(e.key==='ArrowRight'?1:-1)+cases.length)%cases.length;render();document.getElementById('hiw-tab-'+active).focus()});
panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){const list=[...panel.querySelectorAll('button:not([hidden]),textarea,input:not([hidden])')].filter(x=>!x.disabled&&x.getClientRects().length&&x.getAttribute('tabindex')!=='-1');if(!list.length)return;if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list[list.length-1].focus()}else if(!e.shiftKey&&document.activeElement===list[list.length-1]){e.preventDefault();list[0].focus()}}});
document.getElementById('hiw-save').addEventListener('click',()=>{notes[active]=document.getElementById('hiw-notes').value;try{localStorage.setItem(KEY,JSON.stringify(notes));document.getElementById('hiw-status').textContent='Notiz lokal gespeichert. Bitte zusätzlich JSON-Backup erstellen.'}catch{document.getElementById('hiw-status').textContent='Lokale Speicherung nicht möglich. Bitte JSON-Backup erstellen.'}});
document.getElementById('hiw-export').addEventListener('click',()=>{notes[active]=document.getElementById('hiw-notes').value;const b=new Blob([JSON.stringify({version:1,notes},null,2)],{type:'application/json'});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='Beyond-the-CV-How-I-Work.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)});
document.getElementById('hiw-import').addEventListener('click',()=>document.getElementById('hiw-file').click());document.getElementById('hiw-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>100000)throw Error('Datei zu groß');const data=JSON.parse(await f.text());if(!data.notes||typeof data.notes!=='object'||Array.isArray(data.notes))throw Error('Ungültige Daten');const clean={};for(let i=0;i<cases.length;i++)if(typeof data.notes[i]==='string')clean[i]=data.notes[i].slice(0,1600);notes=clean;localStorage.setItem(KEY,JSON.stringify(notes));render();document.getElementById('hiw-status').textContent='Notizen importiert.'}catch(err){document.getElementById('hiw-status').textContent='Import fehlgeschlagen: '+err.message}e.target.value=''});
})();
